-- AI/ML pathway ("Cipher Division") Act 8 -- "Classification" content.
-- Arc II, "Machines That Predict." 1 campaign, 2 operations, 12 missions
-- (11 lessons + boss), following the same campaigns -> operations ->
-- missions -> dialogue -> objectives -> challenges -> hints pattern as
-- every other pathway. Assumes the world-ai-classification row (act_id
-- act-ai-2) already exists from the Act 6-36 spine migration.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-classification', 'world-ai-classification', 'classification', '8A - Classification', 'Turn a probability into a decision under real stakes -- logistic regression, thresholds, confusion matrices, and the precision, recall and F1 tradeoffs that decide whether Cipher Division catches its next real emergency.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-classification-1', 'campaign-ai-classification', 'drawing-the-line', 'Drawing the Line', 'From regression to classification: logistic regression, probabilities, thresholds, and the confusion matrix that shows exactly where a model gets it wrong.', 1),
  ('operation-ai-classification-2', 'campaign-ai-classification', 'the-cost-of-being-wrong', 'The Cost of Being Wrong', 'Accuracy alone is not enough. Precision, recall, F1, ROC-AUC and PR-AUC, chosen around what a missed emergency actually costs.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-classification-01', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-1', 'classification', 'Classification', 'Too many activity spikes, too few analysts to triage them by hand -- and a mistake in the wrong direction that costs far more than a mistake in the other.', 'beginner', ARRAY['maya','byte'], null, null, '{"type":"simulation","simulationId":"classification-vs-regression-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 1),
  ('mission-ai-classification-02', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-1', 'logistic-regression', 'Logistic Regression', 'The simplest model built for this job -- same linear machinery as regression, with one extra step that turns a number into something that behaves like a probability.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"logistic-regression-sim"}'::jsonb, '{"xp":150,"credits":30}'::jsonb, false, 2),
  ('mission-ai-classification-03', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-1', 'probabilities', 'Probabilities', 'Reading what a model''s output number actually means -- and why 0.51 is a far less confident answer than 0.98.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"probability-output-sim"}'::jsonb, '{"xp":150,"credits":30}'::jsonb, false, 3),
  ('mission-ai-classification-04', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-1', 'thresholds', 'Thresholds', 'A probability is not a decision. Somewhere a line has to be drawn, and where it is drawn decides which kind of mistake the system makes more of.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"threshold-tradeoff-sim"}'::jsonb, '{"xp":160,"credits":30}'::jsonb, false, 4),
  ('mission-ai-classification-05', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-1', 'confusion-matrix', 'Confusion Matrix', 'Four outcomes, not one: correctly caught, correctly ignored, false alarm, and the one that matters most -- missed entirely.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"confusion-matrix-sim"}'::jsonb, '{"xp":160,"credits":30}'::jsonb, false, 5),
  ('mission-ai-classification-06', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-1', 'accuracy', 'Accuracy', 'A single number that sounds reassuring and can hide the exact failure Cipher Division cannot afford, once real emergencies are rare enough.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"accuracy-imbalance-sim"}'::jsonb, '{"xp":170,"credits":35}'::jsonb, false, 6),
  ('mission-ai-classification-07', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-2', 'precision', 'Precision', 'Of everything the model called an emergency, how much of it actually was -- the cost of a model that cries wolf.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"precision-sim"}'::jsonb, '{"xp":170,"credits":35}'::jsonb, false, 7),
  ('mission-ai-classification-08', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-2', 'recall', 'Recall', 'Of every real emergency that happened, how many did the model actually catch -- the number Cipher Division should watch closest of all.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"recall-sim"}'::jsonb, '{"xp":180,"credits":35}'::jsonb, false, 8),
  ('mission-ai-classification-09', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-2', 'f1', 'F1', 'One number that will not let a model hide a terrible recall behind a great precision, or the other way around.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"f1-score-sim"}'::jsonb, '{"xp":180,"credits":40}'::jsonb, false, 9),
  ('mission-ai-classification-10', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-2', 'roc-auc', 'ROC-AUC', 'How well a model ranks real emergencies above routine noise, averaged across every threshold it could ever be given.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"roc-auc-sim"}'::jsonb, '{"xp":190,"credits":40}'::jsonb, false, 10),
  ('mission-ai-classification-11', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-2', 'pr-auc', 'PR-AUC', 'The summary score that does not flatter a model just because the thing it needs to catch is rare.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-classification-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"pr-auc-sim"}'::jsonb, '{"xp":190,"credits":40}'::jsonb, false, 11),
  ('mission-ai-classification-12', 'world-ai-classification', 'campaign-ai-classification', 'operation-ai-classification-2', 'the-missed-emergency', 'The Missed Emergency', 'Ninety-seven point eight percent accuracy, and a real emergency that slipped through anyway. Find it, explain why the headline number hid it, and decide what should have been driving this decision from the start.', 'boss', ARRAY['maya','byte'], '{"requiredMissionIds":["mission-ai-classification-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"missed-emergency-boss-sim"}'::jsonb, '{"xp":600,"credits":130,"badgeIds":["the-missed-emergency"],"skillXp":{"classification":50,"ai_ml_fundamentals":15}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-classification-01', 1, 'maya', 'Cipher Labs throws off dozens of activity spikes a day -- power draw, network traffic, subsystem noise. Right now a human decides, case by case, whether each one is real. That does not scale.'),
  ('mission-ai-classification-01', 2, 'maya', 'And scale is not even the real problem. The real problem is direction. A spike we wave off that turns out to be a genuine emergency is a disaster. A spike we flag that turns out to be nothing costs an analyst an hour of attention. Those two mistakes are not the same size, and any system we build has to know that.'),
  ('mission-ai-classification-01', 3, 'byte', 'Act Seven built a model that output a number -- Cipher Labs'' grid load, predicted from Echo-era activity. This is a different shape of problem. We do not need a number here. We need a category: emergency, or not.'),
  ('mission-ai-classification-01', 4, 'byte', 'That is classification -- a model whose output is one of a fixed set of labels, not a value on a continuous scale. Same loop underneath -- data, features, training -- pointed at a different kind of answer.'),

  ('mission-ai-classification-02', 1, 'byte', 'The simplest model built for this job is called logistic regression, and the name is a little misleading -- it is used for classification, not for predicting a number.'),
  ('mission-ai-classification-02', 2, 'byte', 'It starts exactly like linear regression: multiply each feature by a weight, add a bias, sum it up. Linear regression would stop right there and call that the prediction.'),
  ('mission-ai-classification-02', 3, 'byte', 'Logistic regression takes that same linear sum and passes it through one more step -- a function that squashes any value, however large or small, into a number between 0 and 1. That squashing step is the entire difference.'),

  ('mission-ai-classification-03', 1, 'byte', 'That squashing function is called the sigmoid. Feed it any number and it returns something between 0 and 1 -- and Cipher Division treats that output as a probability.'),
  ('mission-ai-classification-03', 2, 'byte', 'A 0.92 from the model means it estimates a 92 percent probability the spike belongs to the emergency class. A 0.51 means it barely leans one way at all.'),
  ('mission-ai-classification-03', 3, 'byte', 'The closer that number sits to 0.5, the less the model actually knows. The closer it sits to 0 or 1, the more confident it is, one way or the other.'),

  ('mission-ai-classification-04', 1, 'byte', 'A probability is not a decision. Cipher Division needs a yes-or-no call on every spike, not a number between 0 and 1.'),
  ('mission-ai-classification-04', 2, 'byte', 'That is what a threshold does -- it draws a cutoff. Above the threshold, call it an emergency. Below it, call it noise. Move that cutoff and you change which kind of mistake the system makes more of.'),
  ('mission-ai-classification-04', 3, 'byte', 'Set it low and the model flags almost everything, catching more real emergencies but drowning us in false alarms. Set it high and false alarms nearly disappear, but so does the model''s willingness to call anything an emergency at all.'),

  ('mission-ai-classification-05', 1, 'byte', 'Every classification has exactly four possible outcomes, and Cipher Division needs a name for each one. Together they are called the confusion matrix.'),
  ('mission-ai-classification-05', 2, 'byte', 'True positive: the model flags an emergency, and it really is one. True negative: it flags nothing, and there really was nothing. Those are the two ways to get it right.'),
  ('mission-ai-classification-05', 3, 'byte', 'False positive: it flags an emergency that was actually noise -- a false alarm. False negative: it flags nothing, and a real emergency slips through unflagged. That last one is the one Cipher Division cannot afford.'),

  ('mission-ai-classification-06', 1, 'byte', 'Accuracy is the simplest score there is: of every spike evaluated, what fraction did the model call correctly -- true positives plus true negatives, over everything.'),
  ('mission-ai-classification-06', 2, 'byte', 'Run it on the first classifier and the number is 97.8 percent. On its face that looks excellent.'),
  ('mission-ai-classification-06', 3, 'byte', 'Here is the trap. Only 11 of the last 1,000 spikes were real emergencies. A model that answered "not an emergency" every single time, with zero intelligence at all, would already score 98.9 percent. Accuracy alone cannot tell a genuinely good model apart from one that just learned the common answer.'),

  ('mission-ai-classification-07', 1, 'byte', 'Precision asks a narrower question: of everything the model called an emergency, how much of it actually was one.'),
  ('mission-ai-classification-07', 2, 'byte', 'The formula is true positives over true positives plus false positives. Run the numbers from the confusion matrix -- 8 true positives, 19 false positives -- and precision comes out to roughly 30 percent.'),
  ('mission-ai-classification-07', 3, 'byte', 'That means seven out of ten emergency flags right now are false alarms. Costly in analyst attention, but not the failure mode Maya is worried about.'),

  ('mission-ai-classification-08', 1, 'byte', 'Recall asks the opposite question: of every real emergency that actually happened, how many did the model catch.'),
  ('mission-ai-classification-08', 2, 'byte', 'The formula is true positives over true positives plus false negatives. Eight caught, three missed, out of eleven real emergencies -- recall comes out to about 73 percent.'),
  ('mission-ai-classification-08', 3, 'byte', 'Given what Maya said in the first briefing -- a missed emergency costs far more than a false alarm -- recall is the number that should worry Cipher Division most, not accuracy.'),

  ('mission-ai-classification-09', 1, 'byte', 'Precision and recall pull in different directions, and Cipher Division usually wants one number, not two, to compare models by. That number is F1.'),
  ('mission-ai-classification-09', 2, 'byte', 'F1 is the harmonic mean of precision and recall -- not a simple average. A simple average lets a model hide a terrible score in one metric behind a great score in the other. Harmonic mean punishes that gap hard.'),
  ('mission-ai-classification-09', 3, 'byte', 'It is a real improvement over accuracy alone. It is still not the final word -- F1 treats precision and recall as equally important, and this Act has already shown that here, they are not.'),

  ('mission-ai-classification-10', 1, 'byte', 'Every metric so far assumed one fixed threshold. ROC-AUC asks a bigger question: across every possible threshold, how well does the model rank real emergencies above routine noise?'),
  ('mission-ai-classification-10', 2, 'byte', 'Trace the true positive rate against the false positive rate at every cutoff, and you get a curve. The area under that curve is the ROC-AUC -- 0.5 means the model ranks no better than a coin flip, 1.0 means perfect ranking.'),
  ('mission-ai-classification-10', 3, 'byte', 'It is threshold-independent, which is genuinely useful. It also treats every part of that curve equally, which becomes a problem when the thing you actually care about is rare.'),

  ('mission-ai-classification-11', 1, 'byte', 'Same idea as ROC-AUC, different curve. Trace precision against recall at every threshold instead of true positive rate against false positive rate, and the area under that curve is PR-AUC.'),
  ('mission-ai-classification-11', 2, 'byte', 'The difference matters more than it sounds. ROC-AUC can look strong even on a model that is mediocre at catching a rare positive class, because negatives are so plentiful the curve stays flattering anyway. PR-AUC does not have that blind spot.'),
  ('mission-ai-classification-11', 3, 'byte', 'With only 11 real emergencies in 1,000 spikes, PR-AUC gives Cipher Division the honest picture. ROC-AUC and accuracy have both already shown they will not.'),

  ('mission-ai-classification-12', 1, 'maya', 'The first version of the classifier is finished. Ninety-seven point eight percent accuracy. On paper that is a strong result, and I do not want to trust it on paper alone.'),
  ('mission-ai-classification-12', 2, 'byte', 'There is a reason not to. Three weeks ago a spike came through at 04:12 -- irregular pattern, no obvious trigger. The classifier scored it 0.31, below the 0.5 threshold. It called it noise.'),
  ('mission-ai-classification-12', 3, 'byte', 'It was not noise. It was a coolant failure starting in Bay Four. Nobody was alerted for eleven minutes, because nothing in the system flagged it.'),
  ('mission-ai-classification-12', 4, 'maya', 'That is a false negative sitting inside a 97.8 percent accuracy score, and accuracy alone would never have told us it was there. Walk the evidence. Read the confusion matrix, explain why the headline number hid this, and tell me which metric should have been driving this decision from the start.'),
  ('mission-ai-classification-12', 5, 'byte', 'Walked it. Recall says it plainly -- the model catches roughly seven real emergencies out of ten, and misses the rest, and accuracy never once had to account for that.'),
  ('mission-ai-classification-12', 6, 'byte', 'There is a second problem underneath the first, though. This model draws exactly one straight-line boundary through the data to separate emergency from not. Coolant failures, network floods and power surges do not all sit on the same side of one line for the same reasons -- they are not that kind of problem.'),
  ('mission-ai-classification-12', 7, 'maya', 'Then we stop asking for a straight line. Next: decision trees -- rules that can branch instead of one boundary that cannot. Get some rest. Tomorrow we build something that bends.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-classification-01-o1', 'mission-ai-classification-01', 1, 'Classification vs regression', 'Sort each task into classification or regression.'),
  ('mission-ai-classification-01-o2', 'mission-ai-classification-01', 2, 'Name the real cost', 'Find the evidence that explains why a missed emergency is worse than a false alarm.'),

  ('mission-ai-classification-02-o1', 'mission-ai-classification-02', 1, 'Spot the shared machinery', 'Identify what logistic regression shares with linear regression.'),
  ('mission-ai-classification-02-o2', 'mission-ai-classification-02', 2, 'Name the missing step', 'Identify the one addition that turns a linear calculation into a logistic regression calculation.'),

  ('mission-ai-classification-03-o1', 'mission-ai-classification-03', 1, 'Read the probability', 'State what a model''s probability output actually means.'),
  ('mission-ai-classification-03-o2', 'mission-ai-classification-03', 2, 'Find the least certain call', 'Identify which of several probability outputs shows the most model uncertainty.'),

  ('mission-ai-classification-04-o1', 'mission-ai-classification-04', 1, 'Define the threshold', 'State what a classification threshold actually does.'),
  ('mission-ai-classification-04-o2', 'mission-ai-classification-04', 2, 'Order the pipeline', 'Put the stages that turn raw features into a final class label in the correct order.'),

  ('mission-ai-classification-05-o1', 'mission-ai-classification-05', 1, 'Name every outcome', 'Sort each scenario into true positive, true negative, false positive or false negative.'),
  ('mission-ai-classification-05-o2', 'mission-ai-classification-05', 2, 'Read the matrix', 'Find how many real emergencies the model failed to catch.'),

  ('mission-ai-classification-06-o1', 'mission-ai-classification-06', 1, 'Define accuracy', 'Choose the correct formula for accuracy.'),
  ('mission-ai-classification-06-o2', 'mission-ai-classification-06', 2, 'Expose the blind spot', 'Find the evidence that shows why accuracy alone can be misleading here.'),

  ('mission-ai-classification-07-o1', 'mission-ai-classification-07', 1, 'Define precision', 'Choose the correct definition of precision.'),
  ('mission-ai-classification-07-o2', 'mission-ai-classification-07', 2, 'Compute it', 'Calculate precision from the confusion matrix counts.'),

  ('mission-ai-classification-08-o1', 'mission-ai-classification-08', 1, 'Define recall', 'Choose the correct definition of recall.'),
  ('mission-ai-classification-08-o2', 'mission-ai-classification-08', 2, 'Find the real cost of missing it', 'Find the evidence that shows the actual cost of low recall in this system.'),

  ('mission-ai-classification-09-o1', 'mission-ai-classification-09', 1, 'Match every metric', 'Match each formula to the metric it defines.'),
  ('mission-ai-classification-09-o2', 'mission-ai-classification-09', 2, 'Explain the harmonic mean', 'State why F1 uses a harmonic mean rather than a simple average.'),

  ('mission-ai-classification-10-o1', 'mission-ai-classification-10', 1, 'Define ROC-AUC', 'State what ROC-AUC actually measures.'),
  ('mission-ai-classification-10-o2', 'mission-ai-classification-10', 2, 'Read the extremes', 'Interpret what a ROC-AUC of 0.5 means.'),

  ('mission-ai-classification-11-o1', 'mission-ai-classification-11', 1, 'Define PR-AUC', 'State what PR-AUC actually summarizes.'),
  ('mission-ai-classification-11-o2', 'mission-ai-classification-11', 2, 'Pick the trustworthy score', 'Given how rare real emergencies are, identify the more trustworthy summary score.'),

  ('mission-ai-classification-12-o1', 'mission-ai-classification-12', 1, 'Read the confusion matrix', 'Find the evidence that directly proves a genuine emergency went unflagged.'),
  ('mission-ai-classification-12-o2', 'mission-ai-classification-12', 2, 'Explain why accuracy hid it', 'State why 97.8 percent accuracy failed to surface this false negative.'),
  ('mission-ai-classification-12-o3', 'mission-ai-classification-12', 3, 'Name what should have driven the decision', 'State which metric should have been the deciding factor before this classifier shipped.'),
  ('mission-ai-classification-12-o4', 'mission-ai-classification-12', 4, 'Deliver the verdict', 'Having judged all three, state the revised evaluation standard for the classifier.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-classification-01-o1-c1', 'mission-ai-classification-01-o1', 1, 'drag_and_drop', 'Sort each task into classification or regression.', '{"items":[{"id":"i1","text":"Predict tomorrow''s grid load in megawatts"},{"id":"i2","text":"Decide whether a power spike is an emergency or not"},{"id":"i3","text":"Predict a house''s sale price"},{"id":"i4","text":"Decide whether an email is spam or not"},{"id":"i5","text":"Predict a patient''s body temperature"}],"targets":[{"id":"classification","label":"Classification"},{"id":"regression","label":"Regression"}]}'::jsonb, '{"correctMapping":{"i1":"regression","i2":"classification","i3":"regression","i4":"classification","i5":"regression"}}'::jsonb),
  ('mission-ai-classification-01-o2-c1', 'mission-ai-classification-01-o2', 1, 'investigation', 'Which evidence explains why a missed emergency is worse than a false alarm?', '{"evidence":[{"id":"e1","label":"Incident debrief","detail":"The one historical case where a genuine emergency spike was missed, the human response came 20 minutes late and the incident had already escalated before anyone intervened"},{"id":"e2","label":"Ops dashboard","detail":"False alarms cost roughly one hour of an analyst''s attention each"},{"id":"e3","label":"Facilities log","detail":"Cipher Labs'' power draw fluctuates normally by up to 8 percent per hour"}],"question":"Which evidence explains why a missed emergency is worse than a false alarm?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-classification-02-o1-c1', 'mission-ai-classification-02-o1', 1, 'multiple_choice', 'Logistic regression''s first step -- multiplying features by weights and summing them -- is identical to...', '{"question":"Logistic regression''s first step -- multiplying features by weights and summing them -- is identical to...","options":[{"id":"a","text":"Linear regression''s calculation"},{"id":"b","text":"A decision tree''s splitting rule"},{"id":"c","text":"A clustering algorithm''s distance calculation"},{"id":"d","text":"A fixed, hand-written rule list"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-classification-02-o2-c1', 'mission-ai-classification-02-o2', 1, 'multiple_choice', 'What is the one addition that turns a linear regression calculation into a logistic regression calculation?', '{"question":"What is the one addition that turns a linear regression calculation into a logistic regression calculation?","options":[{"id":"a","text":"More training data"},{"id":"b","text":"A squashing function that maps the linear sum to a value between 0 and 1"},{"id":"c","text":"Removing the bias term"},{"id":"d","text":"Using integers instead of decimal numbers"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-classification-03-o1-c1', 'mission-ai-classification-03-o1', 1, 'multiple_choice', 'Byte''s model outputs 0.92 for a given spike. What does that number mean?', '{"question":"Byte''s model outputs 0.92 for a given spike. What does that number mean?","options":[{"id":"a","text":"There is a 92 percent chance the model is correct about everything"},{"id":"b","text":"The model estimates a 92 percent probability the spike belongs to the emergency class"},{"id":"c","text":"The spike will happen in 92 milliseconds"},{"id":"d","text":"The model is 92 percent finished training"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classification-03-o2-c1', 'mission-ai-classification-03-o2', 1, 'investigation', 'Which spike''s probability output shows the model is most uncertain about the correct class?', '{"evidence":[{"id":"e1","label":"Spike A","detail":"Model output: 0.98"},{"id":"e2","label":"Spike B","detail":"Model output: 0.52"},{"id":"e3","label":"Spike C","detail":"Model output: 0.03"}],"question":"Which spike''s probability output shows the model is most uncertain about the correct class?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-classification-04-o1-c1', 'mission-ai-classification-04-o1', 1, 'multiple_choice', 'What does a classification threshold actually do?', '{"question":"What does a classification threshold actually do?","options":[{"id":"a","text":"It changes how the model computes its probabilities"},{"id":"b","text":"It draws the cutoff that converts a probability into a firm class label"},{"id":"c","text":"It deletes predictions the model is uncertain about"},{"id":"d","text":"It relabels the training data"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classification-04-o2-c1', 'mission-ai-classification-04-o2', 1, 'interactive_diagram', 'Order the pipeline that turns raw features into a final class label.', '{"diagramId":"classification-pipeline","hotspots":[{"id":"linear","label":"Compute the linear sum of features and weights","explanation":"Same first step as linear regression -- multiply, weight, add a bias, sum."},{"id":"sigmoid","label":"Squash the sum into a probability with the sigmoid function","explanation":"The linear sum is passed through the sigmoid to land between 0 and 1."},{"id":"threshold","label":"Compare the probability to a threshold","explanation":"The cutoff decides which side of the line each probability falls on."},{"id":"label","label":"Output the final class label","explanation":"Above the threshold, emergency. Below it, not."}],"task":"Order the classification pipeline stages from first to last."}'::jsonb, '{"correctOrderIds":["linear","sigmoid","threshold","label"]}'::jsonb),

  ('mission-ai-classification-05-o1-c1', 'mission-ai-classification-05-o1', 1, 'drag_and_drop', 'Sort each scenario into true positive, true negative, false positive or false negative.', '{"items":[{"id":"i1","text":"Model flags an emergency; it really was one"},{"id":"i2","text":"Model flags nothing; it really was nothing"},{"id":"i3","text":"Model flags an emergency; it was actually routine noise"},{"id":"i4","text":"Model flags nothing; it was actually a real emergency"}],"targets":[{"id":"tp","label":"True Positive"},{"id":"tn","label":"True Negative"},{"id":"fp","label":"False Positive"},{"id":"fn","label":"False Negative"}]}'::jsonb, '{"correctMapping":{"i1":"tp","i2":"tn","i3":"fp","i4":"fn"}}'::jsonb),
  ('mission-ai-classification-05-o2-c1', 'mission-ai-classification-05-o2', 1, 'investigation', 'Based on the confusion matrix, how many real emergencies did the model fail to catch?', '{"evidence":[{"id":"e1","label":"Confusion matrix","detail":"TP: 8, TN: 970, FP: 19, FN: 3, across 1,000 evaluated spikes"},{"id":"e2","label":"Ops note","detail":"Total spikes evaluated this quarter: 1,000"},{"id":"e3","label":"Model report","detail":"Overall accuracy: 97.8 percent"}],"question":"Based on the confusion matrix, how many real emergencies did the model fail to catch?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-classification-06-o1-c1', 'mission-ai-classification-06-o1', 1, 'multiple_choice', 'Accuracy is defined as...', '{"question":"Accuracy is defined as...","options":[{"id":"a","text":"TP divided by (TP plus FP)"},{"id":"b","text":"(TP plus TN) divided by (TP plus TN plus FP plus FN)"},{"id":"c","text":"TP divided by (TP plus FN)"},{"id":"d","text":"FP divided by (FP plus TN)"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classification-06-o2-c1', 'mission-ai-classification-06-o2', 1, 'investigation', 'Which evidence shows why accuracy alone can be a misleading measure for this problem?', '{"evidence":[{"id":"e1","label":"Emergency rate","detail":"Only 11 of the last 1,000 historical spikes were real emergencies"},{"id":"e2","label":"Baseline check","detail":"A model that always predicted not an emergency, with no intelligence at all, would still score 98.9 percent accuracy"},{"id":"e3","label":"Confusion matrix","detail":"TP: 8, TN: 970, FP: 19, FN: 3"}],"question":"Which evidence shows why accuracy alone can be a misleading measure for this problem?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-classification-07-o1-c1', 'mission-ai-classification-07-o1', 1, 'multiple_choice', 'Precision measures...', '{"question":"Precision measures...","options":[{"id":"a","text":"Of all spikes flagged as emergencies, what fraction actually were"},{"id":"b","text":"Of all real emergencies, what fraction were caught"},{"id":"c","text":"Overall correctness across every spike"},{"id":"d","text":"The area under the ranking curve"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-classification-07-o2-c1', 'mission-ai-classification-07-o2', 1, 'multiple_choice', 'The model flagged 27 spikes as emergencies. Of those, 8 were real. What is the precision?', '{"question":"The model flagged 27 spikes as emergencies. Of those, 8 were real. What is the precision?","options":[{"id":"a","text":"8 divided by 27, roughly 30 percent"},{"id":"b","text":"27 divided by 8"},{"id":"c","text":"8 divided by 1,000"},{"id":"d","text":"19 divided by 27"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-ai-classification-08-o1-c1', 'mission-ai-classification-08-o1', 1, 'multiple_choice', 'Recall measures...', '{"question":"Recall measures...","options":[{"id":"a","text":"Of all spikes flagged as emergencies, what fraction actually were"},{"id":"b","text":"Of all real emergencies, what fraction the model actually caught"},{"id":"c","text":"Overall correctness across every spike"},{"id":"d","text":"How fast the model produces a prediction"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classification-08-o2-c1', 'mission-ai-classification-08-o2', 1, 'investigation', 'Which evidence shows the actual cost of low recall in this system?', '{"evidence":[{"id":"e1","label":"Confusion matrix","detail":"FN: 3 -- three real emergencies were not flagged by the model"},{"id":"e2","label":"Precision report","detail":"Precision: roughly 30 percent"},{"id":"e3","label":"Accuracy report","detail":"Accuracy: 97.8 percent"}],"question":"Which evidence shows the actual cost of low recall in this system?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-classification-09-o1-c1', 'mission-ai-classification-09-o1', 1, 'drag_and_drop', 'Match each formula to the metric it defines.', '{"items":[{"id":"i1","text":"TP / (TP + FP)"},{"id":"i2","text":"TP / (TP + FN)"},{"id":"i3","text":"(TP + TN) / total"},{"id":"i4","text":"Harmonic mean of precision and recall"}],"targets":[{"id":"precision","label":"Precision"},{"id":"recall","label":"Recall"},{"id":"accuracy","label":"Accuracy"},{"id":"f1","label":"F1"}]}'::jsonb, '{"correctMapping":{"i1":"precision","i2":"recall","i3":"accuracy","i4":"f1"}}'::jsonb),
  ('mission-ai-classification-09-o2-c1', 'mission-ai-classification-09-o2', 1, 'multiple_choice', 'Why does F1 use a harmonic mean rather than a simple average of precision and recall?', '{"question":"Why does F1 use a harmonic mean rather than a simple average of precision and recall?","options":[{"id":"a","text":"A harmonic mean is simply easier to compute"},{"id":"b","text":"A harmonic mean punishes a big gap between precision and recall far more than a simple average would, so a model cannot hide a very low score in one behind a high score in the other"},{"id":"c","text":"It is a historical convention with no real reason behind it"},{"id":"d","text":"A harmonic mean always equals accuracy"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-classification-10-o1-c1', 'mission-ai-classification-10-o1', 1, 'multiple_choice', 'ROC-AUC measures...', '{"question":"ROC-AUC measures...","options":[{"id":"a","text":"The model''s raw accuracy at a threshold of 0.5"},{"id":"b","text":"How well the model ranks positive examples above negative ones, averaged across every possible threshold"},{"id":"c","text":"The total number of false negatives"},{"id":"d","text":"How long the model takes to train"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classification-10-o2-c1', 'mission-ai-classification-10-o2', 1, 'multiple_choice', 'An ROC-AUC of 0.5 means...', '{"question":"An ROC-AUC of 0.5 means...","options":[{"id":"a","text":"The model is a perfect classifier"},{"id":"b","text":"The model ranks positives no better than random guessing"},{"id":"c","text":"The model always predicts positive"},{"id":"d","text":"The model has exactly 50 percent precision"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-classification-11-o1-c1', 'mission-ai-classification-11-o1', 1, 'multiple_choice', 'PR-AUC is best described as...', '{"question":"PR-AUC is best described as...","options":[{"id":"a","text":"The area under the curve traced by precision against recall across every threshold"},{"id":"b","text":"The area under the curve traced by true positive rate against false positive rate"},{"id":"c","text":"A single-threshold version of accuracy"},{"id":"d","text":"The average training loss"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-classification-11-o2-c1', 'mission-ai-classification-11-o2', 1, 'investigation', 'Given how rare real emergencies are, which score is the more trustworthy summary of the model?', '{"evidence":[{"id":"e1","label":"Model report","detail":"ROC-AUC: 0.91"},{"id":"e2","label":"Model report","detail":"PR-AUC: 0.62"},{"id":"e3","label":"Class balance","detail":"Only 11 of 1,000 spikes are real emergencies"}],"question":"Given how rare real emergencies are, which score is the more trustworthy summary of the model?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-classification-12-o1-c1', 'mission-ai-classification-12-o1', 1, 'investigation', 'Which evidence directly proves the classifier let a genuine emergency through unflagged?', '{"evidence":[{"id":"e1","label":"Confusion matrix","detail":"TP: 8, TN: 970, FP: 19, FN: 3, across 1,000 evaluated spikes"},{"id":"e2","label":"Incident case, 04:12","detail":"Classifier output: 0.31, below the 0.5 threshold. True label: coolant failure, Bay Four -- a genuine emergency scored as noise"},{"id":"e3","label":"Ops dashboard","detail":"Alert volume dropped 40 percent after the classifier was deployed"}],"question":"Which evidence directly proves the classifier let a genuine emergency through unflagged?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-classification-12-o2-c1', 'mission-ai-classification-12-o2', 1, 'multiple_choice', 'Why did 97.8 percent accuracy fail to surface this false negative?', '{"question":"Why did 97.8 percent accuracy fail to surface this false negative?","options":[{"id":"a","text":"It did not fail -- the number itself was calculated wrong"},{"id":"b","text":"Because real emergencies are rare, correctly predicting the common not-an-emergency case is enough on its own to produce a very high accuracy score, even while the model misses the rare cases that matter most"},{"id":"c","text":"Because accuracy only measures how long training took"},{"id":"d","text":"Because the confusion matrix itself was built incorrectly"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classification-12-o3-c1', 'mission-ai-classification-12-o3', 1, 'multiple_choice', 'Given that missing a real emergency is far more costly than a false alarm, which metric should have been the deciding factor before this classifier shipped?', '{"question":"Given that missing a real emergency is far more costly than a false alarm, which metric should have been the deciding factor before this classifier shipped?","options":[{"id":"a","text":"Accuracy alone"},{"id":"b","text":"Recall, or an F1 weighted toward recall -- the fraction of real emergencies the model actually catches"},{"id":"c","text":"Training loss"},{"id":"d","text":"The number of features used"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-classification-12-o4-c1', 'mission-ai-classification-12-o4', 1, 'boss_encounter', 'Having read the matrix, explained why accuracy hid the failure, and named the metric that should have driven the decision, state the revised evaluation standard.', '{"stages":[{"objectiveRef":"mission-ai-classification-12-o1","label":"Read the confusion matrix"},{"objectiveRef":"mission-ai-classification-12-o2","label":"Explain why accuracy hid it"},{"objectiveRef":"mission-ai-classification-12-o3","label":"Name what should have driven the decision"}],"task":"State Cipher Division''s revised evaluation standard in one sentence: given the cost of a missed emergency, this classifier must be judged on recall and F1 first, and only ships once it is proven, not assumed, to catch what accuracy alone let slip through."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-classification-12-o1","mission-ai-classification-12-o2","mission-ai-classification-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-classification-01-o1-c1', 'orientation', 'Ask whether the output is one of a fixed set of labels, or a value that could be almost any number.', 10, 1),
  ('mission-ai-classification-01-o1-c1', 'solution', 'Classification: deciding whether a spike is an emergency, deciding whether an email is spam. Regression: grid load, sale price, body temperature -- all continuous numbers.', 20, 2),
  ('mission-ai-classification-01-o2-c1', 'orientation', 'Weight the evidence by consequence, not by which one sounds like the bigger inconvenience.', 10, 1),
  ('mission-ai-classification-01-o2-c1', 'solution', 'e1: the one missed emergency in the historical record led to a 20-minute delayed response and an escalated incident -- a cost a false alarm never comes close to.', 20, 2),

  ('mission-ai-classification-02-o1-c1', 'orientation', 'Both models start by combining features and weights the same way, before anything else happens.', 10, 1),
  ('mission-ai-classification-02-o1-c1', 'solution', 'The weighted sum step -- multiply each feature by a weight, add a bias, total it up -- is exactly linear regression''s calculation.', 20, 2),
  ('mission-ai-classification-02-o2-c1', 'orientation', 'Linear regression stops after the weighted sum. Logistic regression does one more thing to it.', 10, 1),
  ('mission-ai-classification-02-o2-c1', 'solution', 'The squashing function that maps the sum into the 0-to-1 range is the entire added step.', 20, 2),

  ('mission-ai-classification-03-o1-c1', 'orientation', 'Treat the output the same way you would treat any probability.', 10, 1),
  ('mission-ai-classification-03-o1-c1', 'solution', '0.92 means the model estimates a 92 percent probability the spike is a genuine emergency, nothing more and nothing less.', 20, 2),
  ('mission-ai-classification-03-o2-c1', 'orientation', 'Uncertainty peaks right around the midpoint of the probability scale.', 10, 1),
  ('mission-ai-classification-03-o2-c1', 'solution', 'e2, at 0.52, sits closest to 0.5 -- the model is barely leaning either way, which is the least confident of the three.', 20, 2),

  ('mission-ai-classification-04-o1-c1', 'orientation', 'A threshold does not touch how the probability itself gets computed.', 10, 1),
  ('mission-ai-classification-04-o1-c1', 'solution', 'A threshold is the cutoff that turns a probability into a firm label -- above it, emergency; below it, not.', 20, 2),
  ('mission-ai-classification-04-o2-c1', 'orientation', 'Nothing can be compared to a threshold before it exists as a probability, and nothing is a probability before the raw sum has been squashed.', 10, 1),
  ('mission-ai-classification-04-o2-c1', 'concept', 'Work backward from the final label: it came from a threshold comparison, which needed a probability, which needed the sigmoid, which needed the linear sum first.', 20, 2),
  ('mission-ai-classification-04-o2-c1', 'solution', 'Linear sum, then sigmoid, then threshold comparison, then the final class label.', 30, 3),

  ('mission-ai-classification-05-o1-c1', 'orientation', 'Ask two questions separately: did the model flag it, and was it actually real?', 10, 1),
  ('mission-ai-classification-05-o1-c1', 'concept', '"Flagged and real" and "not flagged and not real" are the two correct outcomes. The other two combinations are the two kinds of mistakes.', 20, 2),
  ('mission-ai-classification-05-o1-c1', 'solution', 'True positive: flagged and real. True negative: not flagged and not real. False positive: flagged but not real. False negative: not flagged but real.', 30, 3),
  ('mission-ai-classification-05-o2-c1', 'orientation', 'The count you need has a specific name inside the confusion matrix.', 10, 1),
  ('mission-ai-classification-05-o2-c1', 'solution', 'e1: FN is 3 -- the confusion matrix directly states how many real emergencies were missed.', 20, 2),

  ('mission-ai-classification-06-o1-c1', 'orientation', 'Accuracy counts every correct call, of either kind, over every call made.', 10, 1),
  ('mission-ai-classification-06-o1-c1', 'solution', '(TP plus TN) divided by everything -- both correct outcomes, over the total.', 20, 2),
  ('mission-ai-classification-06-o2-c1', 'orientation', 'Ask what a model with zero real intelligence would still score, just by guessing the common answer every time.', 10, 1),
  ('mission-ai-classification-06-o2-c1', 'concept', 'If the positive class is rare enough, even a model that never flags anything can still look accurate.', 20, 2),
  ('mission-ai-classification-06-o2-c1', 'solution', 'e2: an always-predict-negative model would already score 98.9 percent, which proves accuracy alone cannot separate real skill from just guessing the majority class.', 30, 3),

  ('mission-ai-classification-07-o1-c1', 'orientation', 'Precision only looks at the spikes the model actually flagged.', 10, 1),
  ('mission-ai-classification-07-o1-c1', 'solution', 'Of everything flagged as an emergency, what fraction actually was one -- that is precision.', 20, 2),
  ('mission-ai-classification-07-o2-c1', 'orientation', 'True positives divided by everything the model flagged, real or not.', 10, 1),
  ('mission-ai-classification-07-o2-c1', 'solution', '8 divided by 27 is roughly 30 percent.', 20, 2),

  ('mission-ai-classification-08-o1-c1', 'orientation', 'Recall only looks at the spikes that were actually real emergencies.', 10, 1),
  ('mission-ai-classification-08-o1-c1', 'solution', 'Of every real emergency that happened, what fraction the model actually caught -- that is recall.', 20, 2),
  ('mission-ai-classification-08-o2-c1', 'orientation', 'The cost of low recall is measured in what the model missed, not in what it flagged.', 10, 1),
  ('mission-ai-classification-08-o2-c1', 'solution', 'e1: FN of 3 means three genuine emergencies slipped through unflagged -- exactly the cost Maya warned about.', 20, 2),

  ('mission-ai-classification-09-o1-c1', 'orientation', 'Match each formula to the metric name by what it divides by.', 10, 1),
  ('mission-ai-classification-09-o1-c1', 'concept', 'TP over flagged-as-positive is precision. TP over actually-positive is recall. Correct-over-total is accuracy. The formula with no division at all is F1''s harmonic mean.', 20, 2),
  ('mission-ai-classification-09-o1-c1', 'solution', 'TP/(TP+FP) is precision. TP/(TP+FN) is recall. (TP+TN)/total is accuracy. The harmonic mean of precision and recall is F1.', 30, 3),
  ('mission-ai-classification-09-o2-c1', 'orientation', 'Think about what happens to a simple average when one input is very high and the other is very low.', 10, 1),
  ('mission-ai-classification-09-o2-c1', 'solution', 'A harmonic mean drags the result toward the smaller of the two numbers, so a model cannot fake a good F1 by excelling at only one of precision or recall.', 20, 2),

  ('mission-ai-classification-10-o1-c1', 'orientation', 'ROC-AUC is not tied to any single cutoff -- it looks across all of them at once.', 10, 1),
  ('mission-ai-classification-10-o1-c1', 'solution', 'It measures how well the model ranks positives above negatives, averaged across every possible threshold.', 20, 2),
  ('mission-ai-classification-10-o2-c1', 'orientation', 'A coin flip has no ranking ability at all.', 10, 1),
  ('mission-ai-classification-10-o2-c1', 'solution', '0.5 means the model''s ranking is no better than random chance.', 20, 2),

  ('mission-ai-classification-11-o1-c1', 'orientation', 'PR-AUC swaps out one axis of the ROC curve for a different pair.', 10, 1),
  ('mission-ai-classification-11-o1-c1', 'solution', 'PR-AUC is the area under the curve traced by precision against recall across every threshold.', 20, 2),
  ('mission-ai-classification-11-o2-c1', 'orientation', 'ROC-AUC can look flattering even on a weak model when negatives vastly outnumber positives.', 10, 1),
  ('mission-ai-classification-11-o2-c1', 'solution', 'e2: with only 11 real emergencies in 1,000 spikes, the 0.62 PR-AUC is the honest read -- the 0.91 ROC-AUC is inflated by the sheer number of easy negatives.', 20, 2),

  ('mission-ai-classification-12-o1-c1', 'orientation', 'Look for the one piece of evidence that describes a single real case, not an aggregate statistic.', 10, 1),
  ('mission-ai-classification-12-o1-c1', 'solution', 'e2: a 0.31 score below threshold on a spike that was actually a coolant failure is direct proof of a missed emergency.', 20, 2),
  ('mission-ai-classification-12-o2-c1', 'orientation', 'Think back to the always-predict-negative baseline from earlier in this Act.', 10, 1),
  ('mission-ai-classification-12-o2-c1', 'solution', 'Because real emergencies are so rare, getting the common case right is enough on its own to produce a very high accuracy score, even while missing the rare cases that matter most.', 20, 2),
  ('mission-ai-classification-12-o3-c1', 'orientation', 'The deciding metric should track the mistake that is actually expensive here.', 10, 1),
  ('mission-ai-classification-12-o3-c1', 'solution', 'Recall, or an F1 weighted toward it -- the fraction of real emergencies actually caught -- should have been the deciding factor, given how costly a miss is.', 20, 2),
  ('mission-ai-classification-12-o4-c1', 'orientation', 'Look at what all three judgments point toward as a single standard, not as three separate facts.', 15, 1),
  ('mission-ai-classification-12-o4-c1', 'solution', 'Given the cost of a missed emergency, this classifier must be judged on recall and F1 first, and only ships once it is proven, not assumed, to catch what accuracy alone let slip through.', 25, 2);
